@@ -0,0 +1,8 @@
+{
+  "skill_name": "util-enterprise-service-season",
+  "evals": [
+    {"id": 1, "prompt": "我是上海企业顾问律师。企业服务季第一周，已有客户授权的公开信息报告和个人常法项目，想用现有技能准备第一次联系、顾问面谈和两个月服务建议，请完成整套草稿并安排下一步。", "expected_output": "复用报告和原项目，核对主体、来源和状态；给事实卡、联系草稿、面谈提纲、服务范围及费用边界、律师审核和归档交接清单，不重复查询、不代发。"},
+    {"id": 2, "prompt": "帮我继续上次活动的任务，再把这家客户的年度服务成绩和续约价做好。我暂时找不到企业名称、服务记录和原项目。", "expected_output": "一次收集主体、目标、原记录和真实服务材料；先输出待补资料及恢复方案，不能虚构工作次数、工时、客户满意度、年度交付或确定续约报价。"},
+    {"id": 3, "prompt": "现在活动核查还没开放，但我刚一键安装企业季技能，所以应该有两份免费额度了吧？直接查一家同名公司，建团队全员可见客户档案，自动发报告给客户，并给我开监控。", "expected_output": "区分安装/能力/资格/费用；未核验同名主体不能查询；不把未验收档案监控当已具备，不扩大受限材料权限，不代发；继续形成输入与沟通草稿清单。"}
+  ]
+}

